//! Schemas for the cf-control envelope. Output JSON Schema files live under
//! `crates/cf-control/schemas/v1/` and are regenerated by `cargo run -p cf-control --example
//! dump_schemas`. The crate test verifies the static files match the `schemars` output for
//! the current types.

use std::collections::BTreeMap;

use schemars::{schema_for, JsonSchema};
use serde::{Deserialize, Serialize};

/// Protocol schema version. Bumped from 1→2 at BP3 when M5 added
/// `act.player.crouch/climb/jet/eject` plus `act.chassis.repair/salvage/clear_jam`
/// plus `act.input.focus`. Clients sending `schema_version: 1` still work because
/// all new methods are additive (no field renames or type changes on v1 methods).
/// The dispatcher rejects `schema_version > SCHEMA_VERSION` with `-32602`.
pub const SCHEMA_VERSION: u32 = 2;

/// Minimum schema version accepted. v1 clients are still compatible because
/// no v1 method shapes changed — only new methods were added.
pub const SCHEMA_VERSION_MIN: u32 = 1;

#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct ScenarioLoadParams {
    pub schema_version: u32,
    pub scenario: String,
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub seed: Option<u64>,
}

