/// and rejects subsequent `act.player.*` dispatches; `captured=false`
/// releases. `capturer` carries a short human-readable label.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
